/* Ticket office: renders site/shows/posters.json (generated by scripts/shows/build-posters.ts; nothing typed here),
   reorders by GET /api/tickets/ranking when the server answers, and posts the form to POST /api/tickets (same origin).
   Design and sources: docs/design/ticket-office.md. */
(function () {
  "use strict";
  var REPO = "https://github.com/breakoutwithai/jevnotjev";
  var STAGE = {
    "show": { name: "Tested", sub: "show" },
    "rehearsal": { name: "Small test (under 30 cases)", sub: "rehearsal" },
    "script-reading": { name: "Idea only, not tested", sub: "script reading" }
  };
  /* Same rule as src/backstage/tickets.ts: RFC 5322 dot-atom local part, dot-separated domain labels. */
  var ATOM = "[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+";
  var EMAIL = new RegExp("^(?=.{1,64}@)" + ATOM + "(?:\\." + ATOM + ")*@(?=.{1,253}$)(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\\.)+[A-Za-z]{2,63}$");
  var METHOD = { llm: "LLM", rule: "simple rule", jev: "Jev" };
  function $(id) { return document.getElementById(id); }
  function el(tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; }
  function usd(v) { return v === null ? "n/a" : "$" + (v > 0 && v < 0.01 ? v.toFixed(6) : v.toFixed(2)); }
  function labelsPlain(s) {
    return s.split("; ").map(function (part) {
      /* format/README.md: blind true means picked before seeing any answer or suggestion; false is every other case. */
      var blind = /blind: no/.test(part) ? ", not labelled blind" : /blind: yes/.test(part) ? ", labelled blind" : "";
      return (/human_reviewed/.test(part) ? "drafted by AI, reviewed by a person" : /human/.test(part) ? "picked by a person" : part) + blind;
    }).join("; ");
  }

  var form = $("tkForm"), select = $("tkShow"), wrap = $("tkPosters");
  if (!form || !wrap) return;
  form.querySelector(".tk-submit").disabled = false;
  var MAX = 10;
  var posters = [];
  var requestKey = null;
  function newKey() {
    var a = new Uint8Array(16); crypto.getRandomValues(a);
    return Array.prototype.map.call(a, function (b) { return ("0" + b.toString(16)).slice(-2); }).join("");
  }

  function kind() { return form.querySelector("input[name=kind]:checked").value; }
  function syncKind() {
    var k = kind();
    $("tkShowField").hidden = k !== "show";
    $("tkWebsiteField").hidden = k !== "backstage";
    $("tkIdeaField").hidden = k !== "backstage";
    var p = posters.filter(function (x) { return x.id === select.value; })[0];
    $("tkChosen").textContent = k === "show" ? (p ? "Ticket for: " + p.title : "") : "";
    form.querySelector(".tk-submit").textContent = k === "show" ? "Get my ticket" : "Send my backstage request";
  }
  form.querySelectorAll("input[name=kind]").forEach(function (r) { r.addEventListener("change", syncKind); });
  select.addEventListener("change", syncKind);
  function openPanel() {
    $("officePanel").hidden = false;
    $("officeOpen").setAttribute("aria-expanded", "true");
  }
  if ($("officeOpen")) $("officeOpen").addEventListener("click", function () {
    var open = $("officePanel").hidden;
    $("officePanel").hidden = !open;
    $("officeOpen").setAttribute("aria-expanded", open ? "true" : "false");
  });
  function openHash() {
    if (window.location.hash !== "#tkForm" && window.location.hash !== "#csv") return;
    openPanel();
    if (window.location.hash === "#tkForm") {
      if ($("tkIssued").hidden) reopen();
      if (!form.hidden) form.querySelector("input[name=kind]:checked").focus();
    }
  }
  if (typeof window !== "undefined") openHash();
  if (typeof window !== "undefined") window.addEventListener("load", openHash);
  if (typeof window !== "undefined") window.addEventListener("hashchange", function () {
    openHash();
  });
  function reopen() {
    if (!form.hidden) return;
    $("tkIssued").hidden = true;
    form.reset();
    requestKey = null;
    ["tkShowErr", "tkEmailErr", "tkWebsiteErr", "tkConsentErr", "tkFormErr"].forEach(function (id) { setErr(id, ""); });
    form.querySelectorAll("[aria-invalid]").forEach(function (e) { e.setAttribute("aria-invalid", "false"); });
    /* reset() restores the default "show" choice; keep backstage when the show list failed, then redraw the fields. */
    if (form.querySelector("input[value=show]").disabled) form.querySelector("input[value=backstage]").checked = true;
    syncKind();
    form.hidden = false;
    form.querySelector("input[name=kind]:checked").focus();
  }
  function poster(p) {
    var st = STAGE[p.stage];
    var card = el("article", "tk-poster tk-" + p.stage);
    card.setAttribute("data-id", p.id);
    card.appendChild(el("p", "tk-badge", st.name + " · " + st.sub));
    card.appendChild(el("h3", "", p.title));
    card.appendChild(el("p", "tk-verdict", p.verdictLine));
    card.appendChild(el("p", "tk-why", "Why: " + p.explained.why));
    card.appendChild(el("p", "tk-cases", "What the cases show: " + p.explained.cases));
    card.appendChild(el("p", "tk-next", "Next step: " + p.explained.next));
    if (p.explained.rephrase) card.appendChild(el("p", "tk-rephrase", "Rephrased for Jev: " + p.explained.rephrase));
    if (p.explained.earlier) card.appendChild(el("p", "tk-earlier", "Earlier run: " + p.explained.earlier));
    if (p.run) {
      var r = p.run;
      var counted = r.methods.some(function (m) { return m.labelled > 0; });
      var jev = r.methods.filter(function (m) { return m.arm === "jev"; })[0];
      card.appendChild(el("p", "tk-figure", counted && jev ? "Jev: " + jev.accepted + " of " + jev.labelled + " right" +
        (r.cohorts > 1 ? " on one of its " + r.cohorts + " questions" : "") :
        jev ? "Jev: " + jev.rows + " answers recorded" : "Recorded: " + r.rows + " answers"));
    }
    var primary = el("a", "tk-primary", p.watch ? "Watch now" : p.run ? "Open the evidence" : "Read the idea");
    primary.href = p.watch || (p.run ? REPO + "/tree/main/docs/product/runs/" + p.run.folder : REPO + "/blob/main/" + p.source);
    primary.setAttribute("aria-label", primary.textContent + ": " + p.title);
    card.appendChild(primary);
    var more = el("details", "tk-more");
    more.appendChild(el("summary", "", "More about " + p.title));
    if (p.run) {
      if (r.cohorts > 1 && r.question) more.appendChild(el("p", "tk-scope", "One question: " + r.question));
      if (r.methods.some(function (m) { return m.labelled > 0; })) {
        var ul = el("ul", "tk-methods");
        r.methods.forEach(function (m) {
          ul.appendChild(el("li", "", METHOD[m.arm] + ": " + m.accepted + " of " + m.labelled + " right, spend " + usd(m.spendUsd)));
        });
        more.appendChild(ul);
      } else {
        var recorded = el("ul", "tk-methods");
        r.methods.forEach(function (m) {
          recorded.appendChild(el("li", "", METHOD[m.arm] + ": " + m.rows + " answers recorded, none checked yet, spend " + usd(m.spendUsd)));
        });
        more.appendChild(recorded);
      }
      if (r.labels) more.appendChild(el("p", "tk-labels", "Right answers " + labelsPlain(r.labels) + "."));
    }
    if (p.story) more.appendChild(el("p", "tk-story", p.story));
    more.appendChild(el("p", "tk-date", p.date));
    var count = el("p", "tk-count"); count.hidden = true; more.appendChild(count);
    if (p.run) {
      var links = el("p", "tk-links");
      var ev = el("a", "", "Open the evidence");
      ev.href = REPO + "/tree/main/docs/product/runs/" + p.run.folder;
      ev.setAttribute("aria-label", "Open the evidence: " + p.title);
      links.appendChild(ev);
      more.appendChild(links);
    }
    card.appendChild(more);
    return card;
  }

  function render(order) {
    wrap.innerHTML = "";
    var seen = {};
    var counts = { "show": 0, "rehearsal": 0, "script-reading": 0 };
    order.slice().sort(function (a, b) { return (b.stage === "show") - (a.stage === "show"); }).slice(0, MAX).forEach(function (p) {
      var card = poster(p);
      counts[p.stage]++;
      if (!seen[p.stage]) { card.id = "stage-" + p.stage; seen[p.stage] = true; }
      wrap.appendChild(card);
    });
    document.querySelectorAll(".tk-stages [data-count]").forEach(function (s) { s.textContent = "(" + counts[s.getAttribute("data-count")] + ")"; });
  }

  function fill() {
    var keep = select.value;
    while (select.options.length > 1) select.remove(1);
    posters.filter(function (p) { return p.stage === "show"; }).forEach(function (p) {
      var o = el("option", "", p.title + " (" + STAGE[p.stage].name.toLowerCase() + ")");
      o.value = p.id; select.appendChild(o);
    });
    select.value = keep;
  }

  function catalogueFailed() {
    wrap.textContent = "The show list did not load, so show tickets are paused. Reload the page, or go backstage with your own decision.";
    document.querySelector(".tk-stages").hidden = true;
    var watch = form.querySelector("input[value=show]");
    watch.disabled = true;
    form.querySelector("input[value=backstage]").checked = true;
    syncKind();
  }
  fetch("shows/posters.json").then(function (r) {
    if (!r.ok) throw new Error("posters " + r.status);
    return r.json();
  }).then(function (data) {
    if (!data || !Array.isArray(data.posters)) throw new Error("posters shape");
    posters = data.posters;
    render(posters); fill(); syncKind();
    return fetch("/api/tickets/ranking").then(function (r) { return r.ok ? r.json() : null; }).then(function (rank) {
      if (!rank || !Array.isArray(rank.ids)) return;
      var byId = {};
      posters.forEach(function (p) { byId[p.id] = p; });
      /* Ranked ids first; posters the server does not know (a newer static release) keep their place after them. */
      var ordered = rank.ids.map(function (id) { return byId[id]; }).filter(Boolean);
      var known = {};
      ordered.forEach(function (p) { known[p.id] = true; });
      posters.forEach(function (p) { if (!known[p.id]) ordered.push(p); });
      if (ordered.length) { posters = ordered; render(posters); fill(); syncKind(); }
      var counts = rank.counts || {};
      document.querySelectorAll(".tk-poster").forEach(function (card) {
        var n = counts[card.getAttribute("data-id")];
        if (n > 0) { var c = card.querySelector(".tk-count"); c.textContent = n + (n === 1 ? " ticket issued" : " tickets issued"); c.hidden = false; }
      });
    }).catch(function () { /* Static host with no ticket server: keep the generated order. */ });
  }).catch(catalogueFailed);

  function setErr(id, text, input) {
    var e = $(id); e.textContent = text || ""; e.hidden = !text;
    if (input) input.setAttribute("aria-invalid", text ? "true" : "false");
    return text ? input || e : null;
  }

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var k = kind();
    var email = $("tkEmail").value.trim();
    var bad = [
      setErr("tkShowErr", k === "show" && !select.value ? "Choose a show." : "", select),
      setErr("tkEmailErr", !EMAIL.test(email) ? "Enter an email address, like name@example.com." : "", $("tkEmail")),
      setErr("tkConsentErr", !$("tkConsent").checked ? "Tick this box to get a ticket. We need to keep your email to hold it." : "", $("tkConsent"))
    ].filter(Boolean);
    setErr("tkWebsiteErr", "", $("tkWebsite"));
    setErr("tkFormErr", "");
    if (bad.length) { bad[0].focus(); return; }
    if (!requestKey) requestKey = newKey();
    var body = {
      request_key: requestKey,
      kind: k, email: email, consent: true, follow_up: $("tkFollow").checked,
      show: k === "show" ? select.value : null,
      website: k === "backstage" ? $("tkWebsite").value.trim() : "",
      idea: k === "backstage" ? $("tkIdea").value.trim() : "",
      nickname: form.querySelector("input[name=nickname]").value
    };
    var btn = form.querySelector(".tk-submit"); btn.disabled = true;
    fetch("/api/tickets", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) })
      .then(function (r) { return r.json().then(function (j) { return { status: r.status, body: j }; }); })
      .then(function (res) {
        btn.disabled = false;
        if (res.status === 200 && res.body.ticket) { requestKey = null; return issued(res.body); }
        var field = {
          "bad-email": ["tkEmailErr", "tkEmail", "That email address was not accepted. Check it and try again."],
          "bad-website": ["tkWebsiteErr", "tkWebsite", "That website was not accepted. Use an address like https://example.com, or leave it empty."],
          "bad-show": ["tkShowErr", "tkShow", "Choose a show from the list."],
          "no-consent": ["tkConsentErr", "tkConsent", "Tick this box to get a ticket. We need to keep your email to hold it."]
        }[res.body.code];
        if (field) { setErr(field[0], field[2], $(field[1])).focus(); return; }
        /* The key is kept: if an earlier attempt was stored, the retry returns that ticket instead of a second one. */
        setErr("tkFormErr", {
          "rate-limited": "Too many requests from this network just now. Wait ten minutes and press the button again; if an earlier try went through, you get that same ticket.",
          "request-key-reused": "Your details changed after an earlier try that may have gone through. Reload the page to start a new request.",
          "catalogue-unavailable": "The show list is being updated. Try again in a minute.",
          "tickets-unavailable": "The ticket office is closed right now. Nothing was stored."
        }[res.body.code] || "The ticket could not be issued. Press the button again to retry.");
      })
      .catch(function () {
        btn.disabled = false;
        /* The request may have reached the store; the same request key makes a retry return that ticket, not a second one. */
        setErr("tkFormErr", "We could not confirm your ticket: the connection dropped. Press the button again; the same request is never stored twice.");
      });
  });

  function issued(t) {
    var box = $("tkIssued");
    var p = posters.filter(function (x) { return x.id === t.show; })[0];
    box.innerHTML = "";
    var h = el("h3", "", t.kind === "show" ? "Ticket " + t.ticket + ": " + (p ? p.title : "your show") : "Backstage request " + t.ticket + " received");
    h.tabIndex = -1;
    box.appendChild(h);
    box.appendChild(el("p", "", "Your ticket is this page and its number; we do not email tickets. Quote the number if you ask us to delete your details."));
    if (t.kind === "show" && p) {
      var go = el("p", "tk-links");
      if (p.watch) { var w = el("a", "", "Watch it now"); w.href = p.watch; go.appendChild(w); }
      var ev = el("a", "", p.run ? "Open the evidence" : "Read the idea");
      ev.href = p.run ? REPO + "/tree/main/docs/product/runs/" + p.run.folder : REPO + "/blob/main/" + p.source;
      go.appendChild(ev);
      box.appendChild(go);
    } else {
      box.appendChild(el("p", "", "A person reads each backstage request and replies to your email address. If your decision suits a test, the reply explains how to sign in to Backstage; the request alone does not open it."));
    }
    var another = el("button", "tk-submit", "Get another ticket");
    another.type = "button";
    another.addEventListener("click", reopen);
    box.appendChild(another);
    form.hidden = true;
    box.hidden = false;
    h.focus();
  }
})();
